export interface 유출_목적지 {
  dest_sgg: string;
  dest_sido: string;
  dest_mid: string;
  days: number;
  pct: number;
  is_self: boolean;
  tertiary_days: number;
  general_days: number;
  dialysis_days: number;
  er_days: number;
}

export interface 유입_출처지 {
  orig_sgg: string;
  orig_sido: string;
  orig_mid: string;
  days: number;
  pct: number;
  is_self: boolean;
}

export interface 필수의료_유출입_지표 {
  total: number;
  self: number;
  ri: number;
  top_outflow_sgg?: string | null;
  top_outflow_days?: number;
}

